export const vehicles = sqliteTable('vehicles', {
  id: text('id').primaryKey(), ownerId: text('owner_id').notNull(), plate: text('plate').notNull(),
  brand: text('brand'), model: text('model'), year: integer('year'), stateCode: text('state_code'),
  revision: integer('revision').notNull().default(1), archivedAt: text('archived_at'),
  lastEventId: text('last_event_id').notNull(), createdBy: text('created_by').notNull(), createdAt: text('created_at').notNull(),
  updatedBy: text('updated_by').notNull(), updatedAt: text('updated_at').notNull(),
}, table => [uniqueIndex('idx_vehicles_owner_plate').on(table.ownerId, table.plate),
  index('idx_vehicles_owner_state').on(table.ownerId, table.stateCode),
  check('vehicle_plate_valid', sql`length(${table.plate})=7 AND ${table.plate} GLOB '[A-Z][A-Z][A-Z][0-9][A-Z0-9][0-9][0-9]'`),
  check('vehicle_revision_valid', sql`${table.revision} >= 1`),
  check('vehicle_year_valid', sql`${table.year} IS NULL OR (typeof(${table.year})='integer' AND ${table.year} BETWEEN 1886 AND 9999)`),
  check('vehicle_state_valid', sql`${table.stateCode} IS NULL OR ${table.stateCode} IN ('AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO')`),
]);
